        /* sdd-asis-lifecycle:begin ipt_keyword_onkeyup — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.onEnter()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50011.ipt_keyword_onkeyup' }); }
};

