};

/**
 * @event
 * @name scwin.img_120_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_120_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_120_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fn_List()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'uldmgt50011.img_120_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_printForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_printForm = async function () {
    const sbmOptions = {
        id: "tx_printForm",
        method: "post",
        action: "/filing/form.do",
        ref: "dma_printFormReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50011.tx_printForm" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_fn_List
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_List = async function () {
    const sbmOptions = {
        id: "tx_fn_List",
        method: "post",
        action: "/filing/form.do",
        ref: "dma_ListReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50011.tx_fn_List" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};

/**
 * @method
 * @name scwin.tx_list_xhr
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_list_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_list_xhr", unresolved: "action:self_submit:tx_list_xhr" };
};

/**
 * @method
 * @name scwin.tx_load_list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_load_list = async function () {
    const sbmOptions = {
        id: "tx_load_list",
        method: "post",
        action: "/filing/form.do",
        ref: "dma_loadListReq",
        target: "dlt_formAdmInstTpCds=body.content",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "uldmgt50011.tx_load_list" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.list
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.list = async function () {
    /* sdd-asis-lifecycle:begin list — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form_listForm.action = "/filing/form.do";
    $c.util.getComponent('dma_printFormReq').set('method', "findPrintTargetListOnly");
    await scwin.tx_list_xhr();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onCompleteResponse
 * @author Inswave
 * @date 2026. 09. 29
 * @param responseText
 * @returns
 * @hidden N
*/
scwin.onCompleteResponse = function (responseText) {
    /* sdd-asis-lifecycle:begin onCompleteResponse — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.util.getComponent('formListDiv').innerHTML = responseText;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.search
 * @author Inswave
 * @date 2026. 09. 29
 * @param orderBy
 * @returns
 * @hidden N
*/
scwin.search = async function (orderBy) {
    /* sdd-asis-lifecycle:begin fn_Search — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (orderBy != null) {
        const prevOrderBy = $c.util.getComponent('dma_printFormReq').get('orderBy');
        $c.util.getComponent('dma_printFormReq').set('orderBy', orderBy);
        if (prevOrderBy === orderBy) {
            const ascDiv = $c.util.getComponent('dma_printFormReq').get('ascDiv');
            if (ascDiv === "asc") {
                $c.util.getComponent('dma_printFormReq').set('ascDiv', "desc");
            } else {
                $c.util.getComponent('dma_printFormReq').set('ascDiv', "asc");
            }
        } else {
            $c.util.getComponent('dma_printFormReq').set('ascDiv', "asc");
        }
    } else {
        $c.util.getComponent('dma_printFormReq').set('ascDiv', "asc");
    }
    $c.util.getComponent('dma_printFormReq').set('pageIndex', 1);
    await scwin.list();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.onEnter
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onEnter = async function () {
    /* sdd-asis-lifecycle:begin onEnter — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (event.keyCode == 13) {
        await scwin.search();
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.addForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param formCd formVer formKorNm
 * @returns
 * @hidden N
*/
scwin.addForm = async function (formCd, formVer, formKorNm) {
    /* sdd-asis-lifecycle:begin addForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.voidDiv.setStyle("display", "none");
    if ($c.util.getComponent('targetForm') != null && $c.util.getComponent('targetForm').length != null) {
        if ($c.util.getComponent('targetForm').length >= 20) {
            await $c.win.alert("일괄 인쇄시 20개씩만 선택가능합니다.");
            return;
        }
    }
    if (scwin.existPrintTarget(formCd, formVer)) {
        await $c.win.alert("이미 선택되어 있는 서식입니다.");
        return;
    }
    const ptab = $c.util.getComponent('printTargetList');
    const newTarget = ptab.insertRow();
    const fcd = newTarget.insertCell();
    fcd.id = "targetForm";
    fcd.className = "data_a";
    fcd.innerHTML = formCd + "<input type='hidden' name='printFormCd' value='" + formCd + "' />";
    const fnm = newTarget.insertCell();
    fnm.className = "data_at";
    fnm.innerHTML = formKorNm;
    const fver = newTarget.insertCell();
    fver.className = "data_a";
    fver.innerHTML = formVer + "<input type='hidden' name='printFormVer' value='" + formVer + "' />";
    const del = newTarget.insertCell();
    del.className = "data_a";
    del.innerHTML = "<img src='/img/filing/btn/btn_sub.gif' onclick='delForm(this)' style='cursor:hand' />";
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.existPrintTarget
 * @author Inswave
 * @date 2026. 09. 29
 * @param formCd formVer
 * @returns
 * @hidden N
*/
scwin.existPrintTarget = function (formCd, formVer) {
    /* sdd-asis-lifecycle:begin existPrintTarget — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (document.listForm.printFormCd == null) {
        return false;
    } else {
        if (document.listForm.printFormCd.length == null || document.listForm.printFormCd.length == 1) {
            if (document.listForm.printFormCd.value === formCd && document.listForm.printFormVer.value === formVer) {
                return true;
            }
        } else {
            for (let i = 0; i < document.listForm.printFormCd.length; i++) {
                if (document.listForm.printFormCd[i].value === formCd && document.listForm.printFormVer[i].value === formVer) {
                    return true;
                }
            }
        }
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


function delForm(obj) {
    /* sdd-asis-lifecycle:begin delForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const trNode = obj.parentNode.parentNode;
    const tbNode = trNode.parentNode;
    tbNode.removeChild(trNode);
    if (document.listForm.printFormCd == null) {
        scwin.voidDiv.setStyle("display", "block");
    }
    /* sdd-asis-lifecycle:end */
}

/**
 * @method
 * @name scwin.printForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.printForm = async function () {
    /* sdd-asis-lifecycle:begin printForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const _url = "/filing/form/ULDMGT50012_i0.jsp";
    const _props = "toolbar=no,menubar=no,scrollbars=yes,status=yes,resizable=yes,width=700,height=700";
    await $c.win.openPopup((function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(_url), { id: "printView", popupName: "printView", width: "700", height: "700", resizable: true, scrollbars: true }, {});
    $c.util.getComponent('dma_printFormReq').set('method', "printTargetList");
    scwin.form_listForm.target = "printView";
    scwin.form_listForm.action = "/filing/form.do";
    await scwin.tx_printForm();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fn_List
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_List = async function () {
    /* sdd-asis-lifecycle:begin fn_List — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    scwin.form_listForm.action = "/filing/form.do";
    $c.util.getComponent('dma_printFormReq').set('method', "");
    scwin.form_listForm.target = "";
    await scwin.tx_fn_List();
    /* sdd-asis-lifecycle:end */
};
